// Field UI uses the same records and transition rules as the management workspaces.
function workerNext(t){
 if(t.impact||t.hold)return b('查看暂停原因','taskDetail',t.id);
 if(t.status==='new')return b('接收任务','receive',t.id,'primary');
 if(t.status==='received')return b('确认条件，开始施工','start',t.id,'primary');
 if(t.status==='active')return b(t.done>=t.planned?'提交完工验收':'记进度',''+(t.done>=t.planned?'taskSubmit':'log'),t.id,'primary');
 return b('查看进展','taskDetail',t.id);
}
function workerTask(t){return `<article class="fieldcard"><div class="row between">${status(t.status)}<span class="quiet">截至 ${esc(t.due)}</span></div><h2>${esc(t.title)}</h2><p>${esc(t.location)}</p><div class="fieldprogress"><strong>${t.done}<small> / ${t.planned} 块</small></strong><span>已记录完成量</span></div><div class="progress"><i style="width:${Math.min(100,t.done/t.planned*100)}%"></i></div>${t.impact||t.hold?'<div class="note dangerNote">请暂停受影响作业，等待处理</div>':''}<div class="fieldbuttons">${workerNext(t)}${b('任务详情','taskDetail',t.id)}</div></article>`;}
function workerIssue(i){const mine=['rectify','evidence','supplement'].includes(i.status);return `<article class="fieldcard compact"><div class="row between">${status(i.status)}${mine?tag('需要我处理','amber'):tag(i.status==='closed'?'已结束':'等待办理')}</div><h3>${esc(i.title)}</h3><p>${esc(i.location)}</p><div class="row between"><span class="quiet">${mine?'期限：'+esc(i.due):'办理人：'+esc(i.owner)}</span>${b(mine?'去处理':'看进展','issueDetail',i.id)}</div></article>`;}
function workerTaskDetail(id){const t=S.tasks.find(x=>x.id===id);if(!t)return empty();const d=S.drawings.find(x=>x.id===t.drawing),related=S.issues.filter(i=>i.task===id),a=S.acceptances.find(x=>x.target===id&&x.status==='pending');return b('‹ 我的任务','overviewPage','','link detailback')+`<h1>${esc(t.title)}</h1><p class="fieldlocation">${esc(t.location)}</p>${status(t.status)}<section class="fieldcard"><div class="fieldprogress"><strong>${t.done}<small> / ${t.planned} 块</small></strong><span>已记录完成量</span></div><div class="progress"><i style="width:${Math.min(100,t.done/t.planned*100)}%"></i></div><p>施工范围：${esc(t.scope)}</p><div class="row between"><span>施工图 ${esc(d?.rev||'未绑定')}</span>${b('打开图纸','drawingDetail',t.drawing)}</div><details class="fieldfold"><summary>查看施工与自检要求</summary><p>${esc(t.checks)}</p><p>开工前确认交底、人员设备及必要作业审批。</p></details>${t.impact||t.hold?`<div class="note dangerNote">${esc(t.impact||t.hold)}</div>`:''}${t.returnReason?`<div class="note dangerNote">请处理：${esc(t.returnReason)}</div>`:''}${t.status==='pending'?'<div class="note">已提交，等待验收。完成量不等于验收通过。</div>':''}<div class="fieldbuttons">${['new','received','active'].includes(t.status)?workerNext(t):''}${a?b('查看验收进展','acceptDetail',a.id):''}${t.status!=='complete'?b('发现问题','report',t.id,'danger'):''}</div></section><h2 class="fieldsection">这项任务的问题</h2>${related.map(workerIssue).join('')||empty('暂无关联问题')}<details class="fieldcard"><summary>施工记录 · ${t.records.length} 条</summary>${t.records.map(r=>`<div class="fieldrecord"><strong>新增 ${r.quantity} 块</strong><p>${esc(r.text)}</p>${files(r.files)}<span class="quiet">${esc(r.time)}</span></div>`).join('')}</details><details class="fieldcard"><summary>办理历史</summary>${timeline(id)}</details>`;}
function workerIssueDetail(id){const i=S.issues.find(x=>x.id===id);if(!i)return empty();const mine=['rectify','evidence','supplement'].includes(i.status);return b('‹ 返回现场事项','issuesPage','','link detailback')+`<h1>${esc(i.title)}</h1><p class="fieldlocation">${esc(i.location)}</p>${status(i.status)}<section class="fieldcard"><h2>${mine?'现在需要你做':'当前处理进展'}</h2>${mine?`<p>${esc(i.request||i.returnReason||i.plan)}</p><div class="note"><strong>检查要求</strong><br>${esc(i.criteria||'按补充要求提交现场记录与证据')}</div>`:`<p>由 ${esc(i.owner)} 继续办理。</p><p class="quiet">${i.status==='closed'?'问题已验收关闭。':'有新安排会通知你，无需重复上报。'}</p>`}${issueActions(i)}${i.status==='pending'?'<p class="quiet">提交成功不代表验收通过，请等待核验结果。</p>':''}</section><details class="fieldcard"><summary>原始问题与附件</summary><p>${esc(i.description)}</p>${files(i.files)}${voiceEvidence(i.voiceDraft)}</details>${i.submissions.length?`<details class="fieldcard"><summary>我提交的整改记录 · ${i.submissions.length} 次</summary>${i.submissions.map(x=>`<div class="fieldrecord"><p>${esc(x.text)}</p><p>${esc(x.value)}</p>${files(x.files)}</div>`).join('')}</details>`:''}<details class="fieldcard"><summary>全部处理记录</summary>${timeline(id)}</details>`;}
function workerMessages(){return '<h1>消息</h1><p class="fieldlocation">有新安排，从这里直接去处理。</p>'+S.messages.filter(m=>m.role==='worker').map(m=>{const i=S.issues.find(x=>x.id===m.object),t=S.tasks.find(x=>x.id===m.object);return `<article class="fieldcard"><p>${esc(m.text)}</p><span class="quiet">${esc(m.time)}</span><div class="fieldbuttons">${i?b('查看事项','issueDetail',i.id,'primary'):t?b('查看任务','taskDetail',t.id,'primary'):b('查看我的事项','issuesPage')}${m.read?tag('已读'):b('标为已读','read',m.id)}</div></article>`;}).join('')+(!S.messages.some(m=>m.role==='worker')?empty('暂无新消息','新安排和处理结果会显示在这里。'):'');}
function workerView(){
 let body='';const section=S.page==='messages'?'messages':S.page==='issues'?'issues':'overview';
 if(S.detail){const {type,id}=S.detail;body=type==='task'?workerTaskDetail(id):type==='issue'?workerIssueDetail(id):b('‹ 返回我的任务','overviewPage','','link detailback')+(type==='drawing'?drawingDetail(id):acceptDetail(id));}
 else if(S.page==='surveys')body=b('‹ 返回我的任务','overviewPage','','link detailback')+Measurements.page();
 else if(section==='messages')body=workerMessages();
 else if(section==='issues')body=`<h1>现场上报</h1><p class="fieldlocation">一次提交问题卡，处理进展在同一卡片跟踪。</p><div class="fieldquick">${b('＋ 新建问题卡','report','','primary')}</div><h2 class="fieldsection">我的现场事项</h2>${S.issues.map(workerIssue).join('')||empty('暂无现场事项')}`;
 else {const todo=S.issues.filter(i=>['rectify','evidence','supplement'].includes(i.status));body=`<div class="fieldwelcome"><span>王班长，辛苦了</span><h1>今天，先做这些</h1><p>滨江商务中心 T2 · 幕墙安装一班</p></div>${todo.length?`<div class="fieldnotice">有 ${todo.length} 项整改或补资料需要你处理 ${b('去看看','issuesPage','','link')}</div>`:''}<h2 class="fieldsection">我的任务</h2>${S.tasks.map(workerTask).join('')||empty('暂无任务','新任务会出现在这里。')}<div class="fieldquick">${b('＋ 发现问题','report')}${b('⌁ 基层测量','surveysPage')}</div><p class="quiet">提交后查看状态即可，不必重复填写。</p>`;}
 const unread=S.messages.filter(m=>m.role==='worker'&&!m.read).length;
 return `<div class="worker-shell"><header class="worker-top"><strong>匠 <span>工程排障助手</span></strong><details class="demo-switch"><summary>演示设置</summary><label for="role">切换演示角色</label><select id="role" aria-label="切换演示角色">${Object.entries(M.people).map(([v,l])=>`<option value="${v}" ${v===S.role?'selected':''}>${l}</option>`).join('')}</select>${b('重置','reset','','small')}</details></header><main class="worker-content">${body}<p class="field-demo">本地原型 · 示例数据 · 附件仅保存本机</p></main><nav class="worker-tabs" aria-label="施工端导航">${[['overview','▤','我的任务'],['issues','＋','现场上报'],['messages','♧','消息']].map(([p,icon,l])=>`<button data-page="${p}" class="${section===p?'active':''}"><span>${icon}${p==='messages'&&unread?`<i>${unread}</i>`:''}</span>${l}</button>`).join('')}</nav></div>`;
}
